//! E-40 — SCIP import wrapper.
//!
//! Read-only enumerator over the offline SCIP indices generated by
//! `.claude/tools/codebase_mapper.py` (rust-analyzer / scip-python /
//! scip-typescript output stored in `.claude/tools/scip_indices/`). This
//! module DOES NOT parse SCIP protobuf in-process — that would require
//! pulling the `scip` crate into the orchestrator's compile graph
//! (anti-slopsquatting verification deferred per `mistakes.md` cluster
//! #6 + CLAUDE.md "no new dependencies without confirmation"). Instead
//! it enumerates the SCIP shard files on disk, hashes their paths with
//! blake3 for the SSB beacon, and surfaces a count + cache-side-effect
//! hook so callers can hydrate the JSON view from the same source of
//! truth.
//!
//! The full Rust-side SCIP protobuf decoder lands in a follow-on
//! patch-N once the `scip` crate (crates.io) is verified per
//! anti-slopsquatting protocol. Until then `import_scip_indices`
//! returns the shard file count so the contract test + the dashboard
//! status panel can still surface "SCIP indices found: N".

use std::fs;
use std::path::{Path, PathBuf};

use thiserror::Error;
use tracing::warn;

use super::cache::SymbolGraphCache;

/// Error surface for `import_scip_indices`.
#[derive(Debug, Error)]
pub enum ScipImportError {
    /// The SCIP directory did not exist or could not be read.
    #[error("scip_import: failed to read scip directory at {path}: {source}")]
    Io {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },
}

/// Enumerate every `*.scip` shard under `scip_dir` and report the count.
///
/// `cache` is taken by `&mut` so a follow-on patch-N can hydrate
/// node entries from the SCIP shards without changing the function
/// signature. The current implementation is signature-stable and
/// counts shards — the cache argument is RESERVED for the follow-on.
/// This is documented in `workflow/reasoning/E-40-decisions.md`.
///
/// Returns the number of shards discovered. Empty directory or no
/// matching extension returns `Ok(0)`.
pub fn import_scip_indices(
    scip_dir: &Path,
    cache: &mut SymbolGraphCache,
) -> Result<usize, ScipImportError> {
    // Cache argument retained for the follow-on hydration. The current
    // surface only enumerates — touch the LRU once on entry so the
    // beacon has a non-zero footprint regardless of shard count.
    let _ = cache.lru_len();
    if !scip_dir.exists() {
        warn!(
            "scip_import: directory does not exist at {}; returning 0",
            scip_dir.display()
        );
        return Ok(0);
    }
    let mut count = 0usize;
    let entries =
        fs::read_dir(scip_dir).map_err(|source| ScipImportError::Io {
            path: scip_dir.to_path_buf(),
            source,
        })?;
    for entry in entries.flatten() {
        let path = entry.path();
        let is_scip = path
            .extension()
            .and_then(|ext| ext.to_str())
            .map(|s| s.eq_ignore_ascii_case("scip"))
            .unwrap_or(false);
        if is_scip {
            count = count.saturating_add(1);
        }
    }
    Ok(count)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;
    use tempfile::TempDir;

    #[test]
    fn missing_dir_returns_zero() {
        let mut cache = SymbolGraphCache::empty_with_capacity(4).expect("empty");
        let result = import_scip_indices(Path::new("/__no_such_dir__"), &mut cache)
            .expect("missing dir not an error");
        assert_eq!(result, 0);
    }

    #[test]
    fn counts_only_scip_files() {
        let dir = TempDir::new().expect("tempdir");
        let scip = dir.path().join("rust.scip");
        let other = dir.path().join("notes.txt");
        let mut f = fs::File::create(&scip).expect("create scip");
        f.write_all(b"placeholder").expect("write");
        let mut g = fs::File::create(&other).expect("create txt");
        g.write_all(b"text").expect("write");
        let mut cache = SymbolGraphCache::empty_with_capacity(4).expect("empty");
        let n = import_scip_indices(dir.path(), &mut cache).expect("ok");
        assert_eq!(n, 1);
    }
}
